-- Load every strings.js key/variant into ui_strings (735 rows, generated from src/js/strings.js).
-- Upsert on (key, variant, locale). Rows with status 'planned' (new-flow copy) are left as they are.
on conflict (key, variant, locale) do update
  set condition = excluded.condition, text = excluded.text, note = excluded.note,
      status = excluded.status, updated_at = now()
  where public.ui_strings.status <> 'planned';
